import React from 'react';
import data from './../data/experienceData.js';
import { FaBriefcase, FaMapMarkerAlt, FaCalendarAlt, FaTrophy, FaCode } from 'react-icons/fa';

function Experience() {
  return (
    <section id="experience" className='py-20 px-6 sm:px-8 lg:px-12 bg-gradient-to-br from-[#1a1f26] to-[#20262E]'>
      <div className="max-w-7xl mx-auto">
        {/* Section Header */}
        <div className="text-center mb-16">
          <h2 className="text-4xl sm:text-5xl md:text-6xl font-bold text-white mb-6">
            My <span className="text-[#6699CC]">Experience</span>
          </h2>
          <div className="w-24 h-1 bg-[#6699CC] mx-auto rounded-full mb-8"></div>
          <p className="text-gray-300 text-xl max-w-3xl mx-auto leading-relaxed">
            My professional journey and the impact I've made at each step
          </p>
        </div>

        {/* Timeline */}
        <div className="relative">
          {/* Timeline line */}
          <div className="hidden md:block absolute left-1/2 transform -translate-x-1/2 h-full w-0.5 bg-gradient-to-b from-[#6699CC] to-[#5C4DCE]"></div>

          {data.map((exp, index) => (
            <EnhancedExperienceCard key={exp.id} experience={exp} index={index} />
          ))}
        </div>
      </div>
    </section>
  );
}

// Enhanced Experience Card Component
function EnhancedExperienceCard({ experience, index }) {
  const isEven = index % 2 === 0;

  return (
    <div className={`relative mb-12 md:mb-16 ${
      isEven ? 'md:pr-1/2 md:text-right' : 'md:pl-1/2 md:ml-auto'
    }`}>
      {/* Timeline dot */}
      <div className="hidden md:block absolute top-8 w-6 h-6 bg-[#6699CC] rounded-full border-4 border-[#20262E] ${
        isEven ? 'right-[-12px]' : 'left-[-12px]'
      }"></div>

      {/* Experience Card */}
      <div className="bg-gray-800/50 rounded-2xl border border-gray-700/50 p-8 hover:border-[#6699CC]/50 transition-all duration-300 group">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-6">
          <div className="mb-4 md:mb-0">
            <h3 className="text-2xl font-bold text-white group-hover:text-[#6699CC] transition-colors duration-300">
              {experience.title}
            </h3>
            <div className="flex items-center space-x-2 mt-2">
              <FaBriefcase className="text-[#6699CC]" />
              <span className="text-[#6699CC] font-semibold text-lg">{experience.org}</span>
            </div>
          </div>

          <div className="flex flex-col space-y-2">
            <div className="flex items-center space-x-2">
              <FaCalendarAlt className="text-gray-400" />
              <span className="text-gray-300">{experience.date}</span>
            </div>
            <div className="flex items-center space-x-2">
              <FaMapMarkerAlt className="text-gray-400" />
              <span className="text-gray-300">{experience.location}</span>
            </div>
            <span className={`px-3 py-1 rounded-full text-xs font-medium w-fit ${
              experience.type === 'Full-time' ? 'bg-green-500/20 text-green-400' :
              experience.type === 'Internship' ? 'bg-blue-500/20 text-blue-400' :
              'bg-purple-500/20 text-purple-400'
            }`}>
              {experience.type}
            </span>
          </div>
        </div>

        <p className="text-gray-300 text-lg mb-6 leading-relaxed">
          {experience.description}
        </p>

        {/* Responsibilities */}
        <div className="mb-6">
          <h4 className="text-lg font-semibold text-white mb-3">Key Responsibilities:</h4>
          <ul className="space-y-2">
            {experience.responsibilities.map((resp, idx) => (
              <li key={idx} className="flex items-start space-x-3">
                <span className="w-2 h-2 bg-[#6699CC] rounded-full mt-2 flex-shrink-0"></span>
                <span className="text-gray-300">{resp}</span>
              </li>
            ))}
          </ul>
        </div>

        {/* Achievements */}
        <div className="mb-6">
          <h4 className="text-lg font-semibold text-white mb-3 flex items-center">
            <FaTrophy className="text-[#6699CC] mr-2" />
            Key Achievements:
          </h4>
          <ul className="space-y-2">
            {experience.achievements.map((achievement, idx) => (
              <li key={idx} className="flex items-start space-x-3">
                <span className="w-2 h-2 bg-green-400 rounded-full mt-2 flex-shrink-0"></span>
                <span className="text-gray-300">{achievement}</span>
              </li>
            ))}
          </ul>
        </div>

        {/* Technologies */}
        <div>
          <h4 className="text-lg font-semibold text-white mb-3 flex items-center">
            <FaCode className="text-[#6699CC] mr-2" />
            Technologies Used:
          </h4>
          <div className="flex flex-wrap gap-2">
            {experience.technologies.map((tech, idx) => (
              <span key={idx} className="px-3 py-1 bg-[#6699CC]/20 text-[#6699CC] rounded-full text-sm">
                {tech}
              </span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default Experience;
